var MIN={pl:'min',de:'Min.',tr:'dk',es:'min',fr:'min',ar:'د'};
var OF={pl:'{n} z 20 projektów przejrzanych',de:'{n} von 20 Projekten angesehen',tr:'20 projeden {n} tanesi incelendi',es:'{n} de 20 proyectos explorados',fr:'{n} projets explorés sur 20',ar:'تمت مشاهدة {n} من 20 مشروعًا'};
var ADDED={pl:'Dodano',de:'Hinzugefügt am',tr:'Eklendi:',es:'Añadido el',fr:'Ajouté le',ar:'أضيف في'};
function pick(){var q=new URLSearchParams(location.search).get('lang'),s=null;
  try{s=localStorage.getItem('vm_lang');}catch(_){}
  if(q&&LANGS.indexOf(q)>=0){try{localStorage.setItem('vm_lang',q);}catch(_){}return q;}
  if(s&&LANGS.indexOf(s)>=0)return s;
  var nl=(navigator.languages||[navigator.language||'en']);
  for(var i=0;i<nl.length;i++){var c=String(nl[i]).slice(0,2).toLowerCase();if(LANGS.indexOf(c)>=0)return c;}
  return 'en';}
var L=pick(); window.VM_LANG=L;
document.documentElement.lang=L; if(L==='ar')document.documentElement.dir='rtl';
var d=D[L];
function norm(t){return t.replace(/\s+/g,' ').trim();}
function tr(t){var n=norm(t);if(!n)return null;if(d[n])return d[n];var m;
  if(m=n.match(/^Lesson (\d+) · (\d+) min$/))return ({pl:'Lekcja',de:'Lektion',tr:'Ders',es:'Lección',fr:'Leçon',ar:'الدرس'})[L]+' '+m[1]+' · '+m[2]+' '+MIN[L];
  if(m=n.match(/^(\d+) of 20 projects explored$/))return OF[L].replace('{n}',m[1]);
  if(m=n.match(/^(\d+(?:–\d+)?) min$/))return m[1]+' '+MIN[L];
  if(m=n.match(/^Added (\d+ \w{3} \d{4})$/)){var dt=new Date(m[1]);if(!isNaN(dt))return ADDED[L]+' '+dt.toLocaleDateString(L,{day:'numeric',month:'short',year:'numeric'});}
  return null;}
var ATTR=['placeholder','aria-label','title','alt','data-lbl'];
function run(root){if(L==='en')return;
  var w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),n,a=[];
  while(n=w.nextNode()){var p=n.parentElement;if(!p||/^(SCRIPT|STYLE|NOSCRIPT|TEXTAREA|CODE)$/.test(p.tagName)||p.closest('[data-noi18n]'))continue;var t=tr(n.nodeValue);if(t&&t!==norm(n.nodeValue))a.push([n,t]);}
  a.forEach(function(x){var lead=x[0].nodeValue.match(/^\s*/)[0],tail=x[0].nodeValue.match(/\s*$/)[0];x[0].nodeValue=lead+x[1]+tail;});
  var els=root.querySelectorAll?root.querySelectorAll('['+ATTR.join('],[')+']'):[];
  [].forEach.call(els,function(e){ATTR.forEach(function(k){var v=e.getAttribute(k);if(v){var t=tr(v);if(t&&t!==v)e.setAttribute(k,t);}});});
  for(var sel in H[L]){[].forEach.call(document.querySelectorAll(sel),function(e){if(e.dataset.i18n!==L){e.innerHTML=H[L][sel];e.dataset.i18n=L;}});}
}
function switcher(){var top=document.querySelector('.top .wrap');if(!top||document.getElementById('vm-lang'))return;
  var s=document.createElement('select');s.id='vm-lang';s.setAttribute('aria-label','Language');s.setAttribute('data-noi18n','');
  LANGS.forEach(function(c){var o=document.createElement('option');o.value=c;o.textContent='🌐 '+c.toUpperCase();o.title=NAMES[c];if(c===L)o.selected=true;s.appendChild(o);});
  s.onchange=function(){try{localStorage.setItem('vm_lang',s.value);}catch(_){}var u=new URL(location.href);u.searchParams.set('lang',s.value);location.href=u.toString();};
  var cta=document.getElementById('top-cta');top.insertBefore(s,cta&&cta.previousElementSibling&&cta.previousElementSibling.id==='upd-open'?cta.previousElementSibling:cta);
  var st=document.createElement('style');st.textContent='#vm-lang{height:36px;padding:0 8px;border-radius:999px;border:1px solid var(--line);background:transparent;color:var(--mut);font:600 12.5px Inter,sans-serif;cursor:pointer}#vm-lang option{background:#04131d;color:#eafcff}html[dir=rtl] .top .pr{margin-left:0;margin-right:auto}html[dir=rtl] .sg-hp{left:auto!important;right:-9999px!important}html[dir=rtl] body{overflow-x:hidden}@media (max-width:640px){.top .pr{display:none}#vm-lang{padding:0 4px;font-size:11.5px;margin-left:auto}html[dir=rtl] #vm-lang{margin-left:0;margin-right:auto}.top .wrap{gap:8px}}';document.head.appendChild(st);}
function start(){switcher();run(document.body);
  if(L!=='en')new MutationObserver(function(ms){ms.forEach(function(m){if(m.type==='characterData'){var t=tr(m.target.nodeValue);if(t&&t!==m.target.nodeValue)m.target.nodeValue=t;}else m.addedNodes.forEach(function(x){if(x.nodeType===3){var t=tr(x.nodeValue);if(t&&t!==x.nodeValue)x.nodeValue=t;}else if(x.nodeType===1)run(x);});});}).observe(document.body,{childList:true,subtree:true,characterData:true});}
